 rec={'argv':cmd,'returncode':rc,'seconds':round(time.monotonic()-start,3),'process_group_drained':drained,'stdout_sha256':sha(out.read_bytes()),'stderr_sha256':sha(err.read_bytes()),'stderr_bytes':err.stat().st_size};commands.append(rec);(e/(name+'.command.json')).write_text(json.dumps(rec,indent=2)+'\n');assert rc==0 and drained,rec
